#include <bits/stdc++.h>
using namespace std;
#define int long long

void solve(){
    int n; cin>>n;
    int m = 3*n;
    vector<int> arr(m);
    for(int i{}; i < m; i++) cin>>arr[i];
    sort(arr.rbegin(),arr.rend());
    
    vector<int> prefix(m+1,0);
    for(int i{}; i < m; i++){
        prefix[i+1] = prefix[i] + arr[i];
    }
    
    auto calc = [&] (int t1, int t2) -> int
    {
        int add1 = 6LL*prefix[t1];
        int add2 = 4LL*(prefix[t1+2*t2]-prefix[t1]);
        int t3 = n - t1 - t2;
        int add3 = 3LL*(prefix[t1+2*t2+3*t3] - prefix[t1+2*t2]);
        return (add1+add2+add3);
    };
    
    int final_ans = 0;
    for(int t1{}; t1 <= n; t1++){
        int teams_rem = n-t1;
        int left = 0, right = teams_rem;
        int ans = -1;
        while(left <= right){
            int mid1 = left + (right-left)/3;
            int mid2 = left + (2*(right-left))/3;
            int ans1 = calc(t1,mid1);
            int ans2 = calc(t1,mid2);
            ans = max(ans,ans1);
            ans = max(ans,ans2);
            if(ans1 > ans2){
                right = mid2-1;
            }
            else left = mid1+1;
        }
        final_ans = max(final_ans,ans);
    }
    cout<<final_ans<<'\n';
}

signed main() {
	int t; cin>>t;
	while(t--){
	    solve();
	}
}
